#include <Wire.h>
#include <RTClib.h>
#include <DHT.h>
#include <OneWire.h>
#include <DallasTemperature.h>


// ======================================================
// PIN DEFINITIONS
// ======================================================

#define DHT_PIN 2
#define DHT_TYPE DHT11

#define DS18B20_PIN 3

#define START_BUTTON 4

#define MIST_MOSFET 5

#define MOTOR_RELAY 6

#define HEATER_RELAY 7


// ======================================================
// SENSORS
// ======================================================

DHT dht(DHT_PIN, DHT_TYPE);

OneWire oneWire(DS18B20_PIN);
DallasTemperature ds18b20(&oneWire);

RTC_DS3232 rtc;


// ======================================================
// MOTOR SETTINGS
// ======================================================

// برای تست: هر 10 ثانیه
const unsigned long MOTOR_INTERVAL = 10UL * 1000UL;

// موتور 4 ثانیه روشن
const unsigned long MOTOR_RUN_TIME = 4000UL;

bool motorRunning = false;

unsigned long lastMotorRun = 0;
unsigned long motorStartTime = 0;


// ======================================================
// SENSOR TIMING
// ======================================================

unsigned long lastSensorRead = 0;

const unsigned long SENSOR_INTERVAL = 2000UL;


// ======================================================
// HUMIDITY CONTROL
// ======================================================

bool mistRunning = false;


// ======================================================
// TEMPERATURE CONTROL
// ======================================================

// دمای هدف
const float TEMP_LOW = 37.4;
const float TEMP_HIGH = 37.7;


// ======================================================
// HUMIDITY CONTROL
// ======================================================

// برای تست معمولی
const float HUMIDITY_LOW = 50.0;
const float HUMIDITY_HIGH = 58.0;


// ======================================================
// VARIABLES
// ======================================================

float dhtTemperature = 0;
float humidity = 0;
float incubatorTemperature = 0;


// ======================================================
// SETUP
// ======================================================

void setup() {

  Serial.begin(9600);

  // --------------------------
  // OUTPUTS
  // --------------------------

  pinMode(MIST_MOSFET, OUTPUT);
  pinMode(MOTOR_RELAY, OUTPUT);
  pinMode(HEATER_RELAY, OUTPUT);

  // همه خاموش در شروع

  digitalWrite(MIST_MOSFET, LOW);

  // رله‌ها Active LOW
  digitalWrite(MOTOR_RELAY, HIGH);
  digitalWrite(HEATER_RELAY, HIGH);


  // --------------------------
  // START BUTTON
  // --------------------------

  pinMode(START_BUTTON, INPUT_PULLUP);


  // --------------------------
  // DHT11
  // --------------------------

  dht.begin();


  // --------------------------
  // DS18B20
  // --------------------------

  ds18b20.begin();


  // --------------------------
  // RTC
  // --------------------------

  Wire.begin();

  if (!rtc.begin()) {

    Serial.println("ERROR: DS3232 NOT FOUND!");

  } else {

    Serial.println("DS3232 OK");

    if (rtc.lostPower()) {

      Serial.println("RTC LOST POWER");

      // فقط برای تست
      rtc.adjust(DateTime(F(__DATE__), F(__TIME__)));

      Serial.println("RTC SET TO COMPILE TIME");
    }
  }


  // --------------------------
  // START MESSAGE
  // --------------------------

  Serial.println();
  Serial.println("==============================");
  Serial.println(" INCUBATOR TEST SYSTEM");
  Serial.println("==============================");
  Serial.println();

  Serial.println("DHT11: OK");
  Serial.println("DS18B20: OK");
  Serial.println("RTC: OK");

  Serial.println();
  Serial.println("Motor test interval: 10 seconds");
  Serial.println("Motor run time: 4 seconds");
  Serial.println();

  lastMotorRun = millis();
}


// ======================================================
// LOOP
// ======================================================

void loop() {

  unsigned long now = millis();


  // ====================================================
  // READ SENSORS
  // ====================================================

  if (now - lastSensorRead >= SENSOR_INTERVAL) {

    lastSensorRead = now;

    readSensors();

    controlTemperature();

    controlHumidity();

    printInformation();
  }


  // ====================================================
  // MOTOR
  // ====================================================

  controlMotor();


  // ====================================================
  // START BUTTON
  // ====================================================

  checkStartButton();
}


// ======================================================
// READ SENSORS
// ======================================================

void readSensors() {

  // DHT11

  float h = dht.readHumidity();
  float t = dht.readTemperature();

  if (!isnan(h)) {

    humidity = h;
  }

  if (!isnan(t)) {

    dhtTemperature = t;
  }


  // DS18B20

  ds18b20.requestTemperatures();

  float temp = ds18b20.getTempCByIndex(0);

  if (temp != DEVICE_DISCONNECTED_C) {

    incubatorTemperature = temp;
  }
}


// ======================================================
// TEMPERATURE CONTROL
// ======================================================

void controlTemperature() {

  // اگر دما پایین باشد → هیتر روشن

  if (incubatorTemperature < TEMP_LOW) {

    digitalWrite(HEATER_RELAY, LOW);

  }


  // اگر دما بالا باشد → هیتر خاموش

  if (incubatorTemperature > TEMP_HIGH) {

    digitalWrite(HEATER_RELAY, HIGH);

  }
}


// ======================================================
// HUMIDITY CONTROL
// ======================================================

void controlHumidity() {

  // رطوبت کم → مه‌ساز روشن

  if (humidity < HUMIDITY_LOW) {

    digitalWrite(MIST_MOSFET, HIGH);

    mistRunning = true;
  }


  // رطوبت زیاد → مه‌ساز خاموش

  if (humidity > HUMIDITY_HIGH) {

    digitalWrite(MIST_MOSFET, LOW);

    mistRunning = false;
  }
}


// ======================================================
// MOTOR CONTROL
// ======================================================

void controlMotor() {

  unsigned long now = millis();


  // --------------------------
  // START MOTOR
  // --------------------------

  if (!motorRunning &&
      now - lastMotorRun >= MOTOR_INTERVAL) {

    Serial.println(">>> MOTOR ON");

    digitalWrite(MOTOR_RELAY, LOW);

    motorRunning = true;

    motorStartTime = now;
  }


  // --------------------------
  // STOP MOTOR
  // --------------------------

  if (motorRunning &&
      now - motorStartTime >= MOTOR_RUN_TIME) {

    Serial.println("<<< MOTOR OFF");

    digitalWrite(MOTOR_RELAY, HIGH);

    motorRunning = false;

    lastMotorRun = now;
  }
}


// ======================================================
// START BUTTON
// ======================================================

void checkStartButton() {

  static bool previousState = HIGH;

  bool currentState = digitalRead(START_BUTTON);


  if (previousState == HIGH &&
      currentState == LOW) {

    Serial.println();
    Serial.println("**********************");
    Serial.println(" START BUTTON PRESSED");
    Serial.println("**********************");
    Serial.println();

    delay(300);
  }


  previousState = currentState;
}


// ======================================================
// PRINT INFORMATION
// ======================================================

void printInformation() {

  DateTime now = rtc.now();


  Serial.println("--------------------------------");

  Serial.print("RTC: ");

  if (now.hour() < 10)
    Serial.print("0");

  Serial.print(now.hour());

  Serial.print(":");

  if (now.minute() < 10)
    Serial.print("0");

  Serial.print(now.minute());

  Serial.print(":");

  if (now.second() < 10)
    Serial.print("0");

  Serial.println(now.second());


  Serial.print("DS18B20 Temperature: ");
  Serial.print(incubatorTemperature);
  Serial.println(" C");


  Serial.print("DHT11 Temperature: ");
  Serial.print(dhtTemperature);
  Serial.println(" C");


  Serial.print("Humidity: ");
  Serial.print(humidity);
  Serial.println(" %");


  Serial.print("Heater: ");

  if (digitalRead(HEATER_RELAY) == LOW)
    Serial.println("ON");
  else
    Serial.println("OFF");


  Serial.print("Mist Maker: ");

  if (mistRunning)
    Serial.println("ON");
  else
    Serial.println("OFF");


  Serial.print("Motor: ");

  if (motorRunning)
    Serial.println("ON");
  else
    Serial.println("OFF");


  Serial.println("--------------------------------");
}
